import{_ as n,C as r,o as i,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"评分","description":"","frontmatter":{},"headers":[],"relativePath":"components/rating.md","filePath":"components/rating.md","lastUpdated":1787173379000}'),s={name:"components/rating.md"},b={id:"评分",tabindex:"-1"};function u(p,t,g,m,f,x){const l=r("Badge"),a=r("XhDemo");return i(),h("div",null,[d("h1",b,[t[0]||(t[0]=e("评分 ",-1)),o(l,{type:"info",text:"rating"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#评分","aria-label":'Permalink to "评分 <Badge type="info" text="rating" />"'},"​",-1))]),t[3]||(t[3]=c('<p>用一排图案表示一个离散的分值。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>收集或展示满意度、星级这类小范围的主观分值。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>分值范围大（0 到 100）：用<a href="./slider">滑块</a>或<a href="./number-field">数字输入</a>。</li><li>只是展示一个数值：用<a href="./statistic">统计数值</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>allowHalf</code> 支持半档，<code>allowClear</code> 允许再点一次清空。</li><li>悬停预览与实际值分开，<code>onHoverChange</code> 单独回调。</li><li>图案与颜色都可以换。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>不传 value 即为非受控，组件自己维护评分；default-value 只决定初始那一档</p>',10)),o(a,{src:"rating/01-basic"}),t[4]||(t[4]=d("h3",{id:"半星与悬停预览",tabindex:"-1"},[e("半星与悬停预览 "),d("a",{class:"header-anchor",href:"#半星与悬停预览","aria-label":'Permalink to "半星与悬停预览"'},"​")],-1)),t[5]||(t[5]=d("p",null,"allow-half 让落点分左右半边；划过只发 hover-change，评分要点下去才改",-1)),o(a,{src:"rating/02-half"}),t[6]||(t[6]=d("h3",{id:"自定义档数",tabindex:"-1"},[e("自定义档数 "),d("a",{class:"header-anchor",href:"#自定义档数","aria-label":'Permalink to "自定义档数"'},"​")],-1)),t[7]||(t[7]=d("p",null,"count 决定几颗星，星星按 1..count 逐颗写出",-1)),o(a,{src:"rating/03-count"}),t[8]||(t[8]=d("h3",{id:"只读与禁用",tabindex:"-1"},[e("只读与禁用 "),d("a",{class:"header-anchor",href:"#只读与禁用","aria-label":'Permalink to "只读与禁用"'},"​")],-1)),t[9]||(t[9]=d("p",null,"read-only 仍进 Tab 序列、读屏念得出但改不动；disabled 整条退出 Tab 序列",-1)),o(a,{src:"rating/04-readonly-disabled"}),t[10]||(t[10]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=d("p",null,"tone 决定点亮的星用哪族颜色，不写时沿用警示色",-1)),o(a,{src:"rating/05-tone"}),t[12]||(t[12]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=d("p",null,"size 改星的大小与间距，不写即缺省中档",-1)),o(a,{src:"rating/06-size"}),t[14]||(t[14]=d("h3",{id:"自定义图案",tabindex:"-1"},[e("自定义图案 "),d("a",{class:"header-anchor",href:"#自定义图案","aria-label":'Permalink to "自定义图案"'},"​")],-1)),t[15]||(t[15]=d("p",null,"星形由作者写，条目自带这颗的点亮状态，点亮与未点亮可以画成两个字形",-1)),o(a,{src:"rating/07-icon"}),t[16]||(t[16]=d("h3",{id:"自定义颜色",tabindex:"-1"},[e("自定义颜色 "),d("a",{class:"header-anchor",href:"#自定义颜色","aria-label":'Permalink to "自定义颜色"'},"​")],-1)),t[17]||(t[17]=d("p",null,"点亮色与未点亮色各是一个组件令牌，写在行内即可脱开语气档",-1)),o(a,{src:"rating/08-color"}),t[18]||(t[18]=d("h3",{id:"再点一次清空",tabindex:"-1"},[e("再点一次清空 "),d("a",{class:"header-anchor",href:"#再点一次清空","aria-label":'Permalink to "再点一次清空"'},"​")],-1)),t[19]||(t[19]=d("p",null,"allowClear 缺省就开：点中当前那一档清回“还没评”，键盘在最低档再往下走一步同样清零；设为 false 关掉",-1)),o(a,{src:"rating/09-clearable"}),t[20]||(t[20]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-rating&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhRatingControl</code> <code>XhRatingHiddenInput</code> <code>XhRatingItem</code> <code>XhRatingLabel</code> <code>XhRatingRoot</code></td></tr><tr><td>组合式函数</td><td><code>useRating</code></td></tr><tr><td>状态机</td><td><code>ratingMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/rating.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;rating&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>control</code></strong> · <strong><code>item</code></strong> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控评分。给定即受控：内部不再自行落值，只发 onValueChange。</td></tr><tr><td><code>defaultValue</code></td><td><code>number</code></td><td></td><td>非受控初值，缺省 0（还没评）。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>星星颗数，默认 5。</td></tr><tr><td><code>allowHalf</code></td><td><code>boolean</code></td><td></td><td>允许半颗星：档位从 1 变成 0.5。</td></tr><tr><td><code>allowClear</code></td><td><code>boolean</code></td><td></td><td>再点当前档位即清零，键盘在最低档再往下走一步同样清零；默认开。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整个不可交互：退出 Tab 序列，指针与键盘都不认。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：仍可聚焦、仍能被读屏念出，但改不动，也不给悬停预览。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了表单影子才带 name 并参与提交。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 &#39;ltr&#39;。只改写左右方向键与&quot;指针落在哪半边&quot;的语义。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: RatingValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onHoverChange</code></td><td><code>(details: RatingHoverChangeDetails) =&gt; void</code></td><td></td><td>悬停预览变化；指针离开时带 null。它不代表值变了。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>RatingValueChangeDetails</code></td><td>评分变化；detail 为 <code>{ value: number }</code></td></tr><tr><td><code>hover-change</code></td><td><code>RatingHoverChangeDetails</code></td><td>悬停预览变化；detail 为 <code>{ value: number | null }</code>，指针离开时带 null</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhRatingItem</code></td><td><code>default</code></td><td><code>RatingItemSlotProps</code></td><td></td></tr><tr><td><code>XhRatingRoot</code></td><td><code>default</code></td><td><code>RatingRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>VALUE.STEP</code> · <code>VALUE.TO_MIN</code> · <code>VALUE.TO_MAX</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>ITEM.HOVER</code> · <code>HOVER.CLEAR</code> · <code>CONTROL.BLUR</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canInteract</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useRating</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td>已归一化的评分：非法与越界的宿主输入在这里就被夹回来了。</td></tr><tr><td><code>hoveredValue</code></td><td><code>number | null</code></td><td>指针预览值；没有预览（或不可交互）时为 null。</td></tr><tr><td><code>highlightedValue</code></td><td><code>number</code></td><td>当前该点亮到哪：有预览就是预览值，否则就是评分。样式与 data-highlighted 用的都是它。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>还没评（value 为 0）。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>items</code></td><td><code>readonly number[]</code></td><td>1..count 的序号表，作者直接遍历它渲染星星。</td></tr><tr><td><code>getItemState</code></td><td><code>(props: RatingItemProps) =&gt; RatingItemState</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: number) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: RatingItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单出口：一份视觉隐藏的原生输入，随表单提交当前评分。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the control</td><td>整条评分带只占一个 Tab 位：焦点进入锚点那颗星，无锚点时进入容器并由它转投首颗</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowUp</code></td><td>focus in control, not disabled/readOnly</td><td>加一档（allowHalf 时半颗），到顶停在 count；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowDown</code></td><td>focus in control, not disabled/readOnly</td><td>减一档，到底停在最小档，不会退回&quot;还没评&quot;；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>focus in control, not disabled/readOnly</td><td>取最小档（allowHalf 时是半颗，否则一颗）</td></tr><tr><td><code>End</code></td><td>focus in control, not disabled/readOnly</td><td>取满分（count）</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>control</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>control</code></td><td><code>aria-orientation</code></td><td>&#39;horizontal&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>control</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-posinset</code></td><td>item.value</td></tr><tr><td><code>item</code></td><td><code>aria-setsize</code></td><td>ratingMax(prop(&#39;count&#39;))</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/rating.css</code> 按部件选择：<code>[data-scope=&quot;rating&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-half</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-highlighted</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-rating-gap</code> · <code>--xh-rating-item-fg</code> · <code>--xh-rating-item-fg-highlighted</code> · <code>--xh-rating-item-font-size</code> · <code>--xh-rating-item-gap</code> · <code>--xh-rating-item-radius</code> · <code>--xh-rating-label-fg</code> · <code>--xh-rating-label-font-size</code> · <code>--xh-rating-label-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>；只读展示时与<a href="./statistic">统计数值</a>并列。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>档数固定在五档：更多档用户分辨不出差别。</li><li>只读展示时把数值也写出来（4.2 / 5），图案本身读不出精确值。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它展示进度：那是<a href="./progress">进度条</a>。</li><li>不允许清空却也没有默认值，用户误点后改不回来。</li></ul>',48))])}const k=n(s,[["render",u]]);export{P as __pageData,k as default};
